import numpy as np

try:
    from scipy.linalg.lapack import dgeev as _dgeev
except Exception:  # scipy missing at runtime -> fall back to numpy
    _dgeev = None


def _numpy_impl(A):
    eigenvalues, eigenvectors = np.linalg.eig(A)
    idx = int(np.argmax(np.abs(eigenvalues)))
    return eigenvalues[idx], eigenvectors[:, idx]


def find_dominant_eigenvalue_and_eigenvector(A: np.ndarray):
    """
    Find the dominant eigenvalue and eigenvector of a general real square matrix.

    Args:
        A: Real-valued square matrix (accepts numpy arrays) up to size 10x10,
        dtype np.float64.

    Returns:
        eigenvalue: Dominant eigenvalue (numpy scalar, potentially complex)
        eigenvector: Corresponding eigenvector (np.ndarray, potentially complex)
    """
    if _dgeev is None:
        return _numpy_impl(A)

    try:
        Af = np.asfortranarray(A, dtype=np.float64)
        wr, wi, vl, vr, info = _dgeev(Af, compute_vl=0, compute_vr=1,
                                      overwrite_a=1)
        if info != 0:
            return _numpy_impl(A)
        # index of largest magnitude eigenvalue
        i = int(np.argmax(wr * wr + wi * wi))
        if wi[i] == 0.0:
            return wr[i], vr[:, i].astype(np.complex128)
        # complex-conjugate pair: LAPACK stores real part in column j and
        # imaginary part in column j+1 for the eigenvalue with positive
        # imaginary part; the neighbouring eigenvalue is its conjugate.
        val = np.complex128(complex(wr[i], wi[i]))
        if wi[i] > 0.0:
            vec = vr[:, i] + 1j * vr[:, i + 1]
        else:
            vec = vr[:, i - 1] - 1j * vr[:, i]
        return val, vec
    except Exception:
        return _numpy_impl(A)
